import static org.mockito.Mockito.*;
import static com.yuewei.plm.module.masterdata.ProductMoldLifecycleService.*;

/** Transactional, local-only real PostgreSQL regression evidence. No production network/account changes. */
@EnabledIfEnvironmentVariable(named="PLM_MASTER_CRUD_DB_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:15483/plm_foundation_crud_it\\?currentSchema=plm")
class ProductMoldLifecycleLocalIntegrationTest {
    JdbcTemplate jdbc;DataSourceTransactionManager transactions;TransactionStatus transaction;
    final ObjectMapper json=new ObjectMapper().findAndRegisterModules();PilotAccessService access;OperationLogService audit;ProductMoldLifecycleService service;CurrentUser admin;
    @BeforeEach void begin()throws Exception{
        var ds=new DriverManagerDataSource(System.getenv("PLM_MASTER_CRUD_DB_URL"),"postgres",System.getenv("PLM_MASTER_CRUD_DB_PASSWORD"));jdbc=new JdbcTemplate(ds);transactions=new DataSourceTransactionManager(ds);transaction=transactions.getTransaction(new DefaultTransactionDefinition());
        // The shared isolated fixture already has the additive columns. Apply the trigger tail within this rollback scope.
        String migration=Files.readString(Path.of("src/main/resources/db/migration/V20261026_1120__product_mold_lifecycle.sql"));
        if(jdbc.queryForObject("select to_regprocedure('plm_master_data_row_version()') is null",Boolean.class))jdbc.execute(migration.substring(migration.indexOf("CREATE FUNCTION")));
        var a=jdbc.queryForMap("select user_id,username,display_name from sys_user where all_permissions and deleted_flag=0 and status='active' order by user_id limit 1");admin=new CurrentUser(((Number)a.get("user_id")).longValue(),a.get("username").toString(),a.get("display_name").toString(),true);CurrentUserContext.set(admin);
        access=new PilotAccessService(jdbc,json);audit=mock(OperationLogService.class);
        when(audit.logRequired(any(),any())).thenAnswer(inv->{OperationLogCreateCommand command=inv.getArgument(0);CurrentUser actor=inv.getArgument(1);return jdbc.queryForObject("insert into plm_operation_log(request_id,operator_user_id,operator_user_name,action,business_type,business_id,business_code,business_name,detail_json,result,created_by) values(?,?,?,?,?,?,?,?,?,'success',?) returning log_id",Long.class,UUID.randomUUID().toString(),actor.userId(),actor.displayName(),command.getAction(),command.getBusinessType(),command.getBusinessId(),command.getBusinessCode(),command.getBusinessName(),OperationLogDetails.sanitize(command.getDetailJson()),actor.username());});
        service=new ProductMoldLifecycleService(jdbc,json,access,audit,new PhoneModelReferenceService(jdbc,json,new PhoneModelReferenceRepository(jdbc),access,audit));
    }
    @AfterEach void end(){if(transaction!=null&&!transaction.isCompleted())transactions.rollback(transaction);CurrentUserContext.clear();}
    ProductInput input(String name,UUID request){return new ProductInput(name,"product_line",null,null,null,null,null,null,null,1,request,"本地隔离验收补录");}
    long product(){return ((Number)service.createProduct(input("测试基本产品-"+UUID.randomUUID(),UUID.randomUUID()),null).get("id")).longValue();}
    ProductInput update(long id,String name,String material){var p=service.product(id);return new ProductInput(name,p.get("productType").toString(),(Long)p.get("parentProductId"),(String)p.get("code"),(String)p.get("productSpecificCode"),(Long)p.get("phoneModelId"),(String)p.get("model"),material,"本地备注",((Number)p.get("version")).longValue(),UUID.randomUUID(),"更正本地资料");}
    Action action(String kind,long id){return new Action(((Number)service.inspect(kind,id).get("version")).longValue(),UUID.randomUUID(),"隔离验收原因");}
    long master(){return jdbc.queryForObject("insert into plm_collaboration_item(style_name,compatible_models,mold_name,created_by,updated_by) values('隔离款式','原始型号','隔离模具','it','it') returning item_id",Long.class);}
    long moldSet(long item){long id=jdbc.queryForObject("insert into plm_collaboration_mold_set(item_id,set_no,set_name,created_by,updated_by) values(?,1,'隔离套','it','it') returning mold_set_id",Long.class,item);for(String part:List.of("PC","TPU"))jdbc.update("insert into plm_collaboration_mold_part(mold_set_id,part_type) values(?,?)",id,part);return id;}
    long account(boolean engineer,boolean allObjects){
        String name="master-it-"+UUID.randomUUID();
        long id=jdbc.queryForObject("insert into sys_user(user_code,user_name,login_name,username,password_hash,display_name,department_name,status,all_permissions) values(?,?,?,?,?,'基础资料验收','本地','active',false) returning user_id",Long.class,name,name,name,name,"!");
        jdbc.update("insert into plm_pilot_account(user_id,role_code,permissions,all_objects,created_by,updated_by) values(?,'domestic','[\"product:view\",\"collaboration:view\"]'::jsonb,?,'it','it')",id,allObjects);
        if(engineer)jdbc.update("insert into plm_collaboration_assignment(field_group,user_id) values('engineering',?)",id);
        CurrentUserContext.set(new CurrentUser(id,"forged-admin","伪造管理员",true));return id;
    }
    @Test void readOnlyAndForgedAdministratorCannotWrite(){long id=product();account(false,true);assertThat(service.product(id)).containsEntry("canMaintain",false);assertThatThrownBy(()->service.createProduct(input("未授权写入",UUID.randomUUID()),null)).hasMessageContaining("仅工程");assertThatThrownBy(()->service.perform("product",id,"deactivate",new Action(1,UUID.randomUUID(),"尝试"),null)).hasMessageContaining("仅工程");}
    @Test void restrictedReferenceDisclosureIsGenericAndObjectScopeCannotBeBypassed(){long id=product();String privateName="不应泄漏-"+UUID.randomUUID();jdbc.update("insert into plm_product(parent_product_id,product_code,product_name,product_type,version_no,created_by,updated_by) values(?,?,?,'model_variant','V1','it','it')",id,"HIDDEN-"+UUID.randomUUID(),privateName);long actor=account(true,false);jdbc.update("insert into plm_pilot_scope(user_id,entity_type,entity_id) values(?,'product',?)",actor,id);var check=service.inspect("product",id);assertThat(check).containsEntry("hasRestrictedReferences",true).containsEntry("canDelete",false);assertThat(check.get("references")).asString().doesNotContain(privateName).isEqualTo("[]");long another=jdbc.queryForObject("select product_id from plm_product where product_id<>? and deleted_flag=0 order by product_id limit 1",Long.class,id);assertThatThrownBy(()->service.product(another)).hasMessageContaining("未获授权");}
    @Test void basicCreateDoesNotRegisterResearchAndPersistsThroughANewServiceInstance(){long id=product();var db=jdbc.queryForMap("select project_kind,project_registered_at,workflow_template_id,master_data_status from plm_product where product_id=?",id);assertThat(db).containsEntry("project_kind",null).containsEntry("project_registered_at",null).containsEntry("workflow_template_id",null).containsEntry("master_data_status","active");var restarted=new ProductMoldLifecycleService(jdbc,json,access,audit,new PhoneModelReferenceService(jdbc,json,new PhoneModelReferenceRepository(jdbc),access,audit));assertThat(restarted.product(id)).containsEntry("id",id);}
    @Test void ownCreateAndEditAuditDoNotBlockUnusedDeletionAndSameRequestReplaysOnce(){var request=UUID.randomUUID();var input=input("可删除错建产品",request);var created=service.createProduct(input,null);long id=((Number)created.get("id")).longValue();assertThat(service.createProduct(input,null)).isEqualTo(created);service.updateProduct(id,update(id,"已修正名称","PC"),null);assertThat(service.inspect("product",id)).containsEntry("canDelete",true);var action=action("product",id);var deleted=service.perform("product",id,"delete",action,null);assertThat(service.perform("product",id,"delete",action,null)).isEqualTo(deleted);assertThat(jdbc.queryForObject("select deleted_flag from plm_product where product_id=?",Integer.class,id)).isEqualTo(1);assertThatThrownBy(()->service.createProduct(input("另一个档案",request),null)).hasMessageContaining("占用");assertThatThrownBy(()->service.createProduct(input,null)).hasMessageContaining("不能重新创建");}
    @Test void referencedProductCannotDeleteButCanStopAndHistoricalFieldsRemainEditable(){long id=product();long child=jdbc.queryForObject("insert into plm_product(parent_product_id,product_code,product_name,product_type,version_no,created_by,updated_by) values(?,?,'已有型号','model_variant','V1','it','it') returning product_id",Long.class,id,"IT-"+UUID.randomUUID());assertThat(service.inspect("product",id)).containsEntry("canDelete",false);assertThatThrownBy(()->service.perform("product",id,"delete",action("product",id),null)).hasMessageContaining("不能删除");service.perform("product",id,"deactivate",action("product",id),null);assertThatThrownBy(()->requireActive(jdbc,"product",id)).hasMessageContaining("已停用");service.updateProduct(id,update(id,"历史名称更正","PC"),null);assertThat(service.product(id)).containsEntry("status","inactive").containsEntry("name","历史名称更正");assertThat(jdbc.queryForObject("select parent_product_id from plm_product where product_id=?",Long.class,child)).isEqualTo(id);}
    @Test void anyOldWriterInvalidatesTheReadVersion(){long id=product();var action=action("product",id);jdbc.update("update plm_product set remark='另一会话修改' where product_id=?",id);assertThatThrownBy(()->service.perform("product",id,"deactivate",action,null)).hasMessageContaining("其他人修改");}
    @Test void sourceOwnedIdentityCannotBeOverwrittenAndLocalSupplementPersists(){long id=product();jdbc.update("update plm_product set source_system='mes',model='原来源型号' where product_id=?",id);var original=service.product(id);assertThatThrownBy(()->service.updateProduct(id,update(id,"改来源名称","PC"),null)).hasMessageContaining("原系统维护");service.updateProduct(id,update(id,original.get("name").toString(),"PC+TPU"),null);assertThat(service.product(id)).containsEntry("model","原来源型号").containsEntry("material","PC+TPU").containsEntry("sourceOwned",true);}
    @Test void masterOwnCreationAndNameEditsAreNotBusinessAdoption(){long item=master();jdbc.update("insert into plm_collaboration_history(item_id,entity_type,entity_id,field_name,reason,actor_id,actor_name) values(?,'item',?,'moldName','更正名称',?,'it')",item,item,admin.userId());assertThat(service.inspect("item",item)).containsEntry("canDelete",true);service.perform("item",item,"delete",action("item",item),null);assertThat(jdbc.queryForObject("select count(*) from plm_collaboration_history where item_id=?",Long.class,item)).isEqualTo(2);}
    @Test void emptySetCanDeleteButActualPhysicalAndHistoricalFactsCannot(){long item=master(),set=moldSet(item);assertThat(service.inspect("mold_set",set)).containsEntry("canDelete",true);jdbc.update("update plm_collaboration_mold_part set physical_status='confirmed' where mold_set_id=? and part_type='PC'",set);assertThat(service.inspect("mold_set",set)).containsEntry("canDelete",false);service.perform("mold_set",set,"deactivate",action("mold_set",set),null);assertThat(jdbc.queryForObject("select physical_status from plm_collaboration_mold_part where mold_set_id=? and part_type='PC'",String.class,set)).isEqualTo("confirmed");assertThatThrownBy(()->requireActive(jdbc,"mold_set",set)).hasMessageContaining("已停用");assertThat(service.inspect("item",item)).containsEntry("canDelete",false);}
    @Test void uppercaseLegacyOwnerAndRemovedDocumentReferencesRemainProtected(){long id=product();long attachment=jdbc.queryForObject("select attachment_id from plm_attachment order by attachment_id limit 1",Long.class);jdbc.update("insert into plm_document_reference_history(family_id,before_references,after_references,reason,actor_id,actor_name) values(?,?::jsonb,'[]'::jsonb,'历史移除',?,'it')",attachment,"[{\"type\":\"product\",\"id\":"+id+"}]",admin.userId());assertThat(service.inspect("product",id)).containsEntry("canDelete",false);long other=product();jdbc.update("update plm_attachment set owner_object_type='Product',owner_object_id=? where attachment_id=?",other,attachment);assertThat(service.inspect("product",other)).containsEntry("canDelete",false);}
    @Test void reasonAndVersionProtectLifecycleAndFailureRollsBack(){long id=product();var bad=new Action(1,UUID.randomUUID()," ");assertThatThrownBy(()->service.perform("product",id,"deactivate",bad,null)).hasMessageContaining("原因");assertThat(service.product(id)).containsEntry("status","active");}
    @Test void stoppedMasterRejectsNewAdoptionWithoutChangingItsExistingSet(){long item=master(),set=moldSet(item);service.perform("item",item,"deactivate",action("item",item),null);assertThatThrownBy(()->requireActive(jdbc,"item",item)).hasMessageContaining("已停用");assertThat(jdbc.queryForObject("select item_id from plm_collaboration_mold_set where mold_set_id=?",Long.class,set)).isEqualTo(item);service.perform("item",item,"activate",action("item",item),null);assertThatCode(()->requireActive(jdbc,"item",item)).doesNotThrowAnyException();}
    @Test void applicationVisibilityAndCountsUseTheRealApplicationIdentityNotOnlyTheProduct(){long id=product();for(int i=0;i<2;i++)jdbc.update("insert into plm_mold_application(process_code,title,product_line_id,applicant_id,created_by,updated_by) values('local-it',?,?,?,'it','it')","不可泄漏申请-"+i,id,admin.userId());var check=service.inspect("product",id);assertThat(check.get("references")).asString().contains("count=2");long actor=account(true,false);jdbc.update("insert into plm_pilot_scope(user_id,entity_type,entity_id) values(?,'product',?)",actor,id);var hidden=service.inspect("product",id);assertThat(hidden).containsEntry("hasRestrictedReferences",true);assertThat(hidden.get("references")).asString().doesNotContain("不可泄漏申请").isEqualTo("[]");}
    @Test void aRegisteredResearchProjectKeepsItsOriginalEditingAndFreezeRules(){long id=product();jdbc.update("update plm_product set project_kind='product_research',project_registered_at=now(),development_mode='launch_v1',lock_status='frozen' where product_id=?",id);assertThat(service.product(id)).containsEntry("editingPath","/product-research?productId="+id);assertThatThrownBy(()->service.updateProduct(id,update(id,"不得绕开冻结项目","PC"),null)).hasMessageContaining("原项目办理入口");assertThat(service.inspect("product",id)).containsEntry("canDelete",false);}
    @Test void anUnknownLocalPlatformCodeCanBeAssignedOnceAndItsHistoryRemainsOccupied(){
        long id=product();String code=null;
        for(String next:List.of("QZ","ZQ","QX","XQ","ZX","XZ"))if(jdbc.queryForObject("select count(*) from plm_product where product_type='product_line' and product_specific_code=?",Long.class,next)==0){code=next;break;}
        assertThat(code).isNotNull();var p=service.product(id);
        service.updateProduct(id,new ProductInput(p.get("name").toString(),"product_line",null,p.get("code").toString(),code,null,null,null,null,((Number)p.get("version")).longValue(),UUID.randomUUID(),"工程首次分配两位产品码"),null);
        assertThat(service.product(id)).containsEntry("productSpecificCode",code);
        var changed=service.product(id);String other=code.equals("QZ")?"ZQ":"QZ";
        assertThatThrownBy(()->service.updateProduct(id,new ProductInput(changed.get("name").toString(),"product_line",null,changed.get("code").toString(),other,null,null,null,null,((Number)changed.get("version")).longValue(),UUID.randomUUID(),"不能重新换码"),null)).hasMessageContaining("不可改写");
        service.perform("product",id,"delete",action("product",id),null);String occupied=code;
        assertThatThrownBy(()->service.createProduct(new ProductInput("不得复用历史码","product_line",null,null,occupied,null,null,null,null,1,UUID.randomUUID(),"尝试重用"),null)).hasMessageContaining("历史资料占用");
    }
    @Test void modelUsesTheChosenStandardPhoneAndRetainsItsLeadingZeroCode(){
        long parent=product();jdbc.update("update plm_product set product_specific_code='ZQ' where product_id=?",parent);
        long brand=jdbc.queryForObject("insert into plm_phone_brand(name,created_by,updated_by) values(?,'it','it') returning id",Long.class,"隔离品牌-"+UUID.randomUUID());
        var codes=jdbc.queryForList("select code_item_id from plm_code_item where code_type='phone_model' and code_value='0052' and status='enabled' and deleted_flag=0",Long.class);
        long code=codes.isEmpty()?jdbc.queryForObject("insert into plm_code_item(code_type,code_value,code_name,status) values('phone_model','0052','隔离原编码','enabled') returning code_item_id",Long.class):codes.get(0);
        long phone=jdbc.queryForObject("insert into plm_phone_model_member(brand_id,model_name,code_item_id,created_by,updated_by) values(?,'原始标准型号',?,'it','it') returning id",Long.class,brand,code);
        var created=service.createProduct(new ProductInput("基本型号","model_variant",parent,null,null,phone,null,null,null,1,UUID.randomUUID(),"明确选择标准手机"),null);
        assertThat(jdbc.queryForMap("select phone_model_member_id,phone_model_code,model,product_specific_code,project_kind from plm_product where product_id=?",created.get("id"))).containsEntry("phone_model_member_id",phone).containsEntry("phone_model_code","0052").containsEntry("model","原始标准型号").containsEntry("product_specific_code","ZQ").containsEntry("project_kind",null);
        jdbc.update("update plm_phone_brand set status='disabled' where id=?",brand);
        assertThatThrownBy(()->service.createProduct(new ProductInput("不可新采用","model_variant",parent,null,null,phone,null,null,null,1,UUID.randomUUID(),"停用品牌后尝试新采用"),null)).hasMessageContaining("启用的品牌");
        assertThat(service.product(((Number)created.get("id")).longValue())).containsEntry("phoneModelId",phone);
    }
    @Test void adoptionShareLockSerializesDeleteAndTheNewReferenceIsRechecked() throws Exception {
        transactions.rollback(transaction);transaction=null;
        String code="CONCURRENCY-"+UUID.randomUUID();
        long id=jdbc.queryForObject("insert into plm_product(product_code,product_name,product_type,version_no,created_by,updated_by) values(?,'并发验收父档','product_line','V1','it','it') returning product_id",Long.class,code);
        var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var locked=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var deleting=new java.util.concurrent.CountDownLatch(1);
        try {
            var writer=pool.submit(()->{CurrentUserContext.set(admin);try{return new TransactionTemplate(transactions).execute(status->{requireActive(jdbc,"product",id);locked.countDown();try{if(!release.await(10,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("并发测试超时");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return jdbc.queryForObject("insert into plm_product(parent_product_id,product_code,product_name,product_type,version_no,created_by,updated_by) values(?,?,'并发实际采用','model_variant','V1','it','it') returning product_id",Long.class,id,code+"-CHILD");});}finally{CurrentUserContext.clear();}});
            assertThat(locked.await(5,java.util.concurrent.TimeUnit.SECONDS)).isTrue();
            var delete=pool.submit(()->{CurrentUserContext.set(admin);try{return new TransactionTemplate(transactions).execute(status->{deleting.countDown();return service.perform("product",id,"delete",new Action(1,UUID.randomUUID(),"并发错建删除验收"),null);});}finally{CurrentUserContext.clear();}});
            assertThat(deleting.await(5,java.util.concurrent.TimeUnit.SECONDS)).isTrue();
            assertThatThrownBy(()->delete.get(250,java.util.concurrent.TimeUnit.MILLISECONDS)).isInstanceOf(java.util.concurrent.TimeoutException.class);
            release.countDown();long child=writer.get(10,java.util.concurrent.TimeUnit.SECONDS);
            assertThatThrownBy(()->delete.get(10,java.util.concurrent.TimeUnit.SECONDS)).isInstanceOf(java.util.concurrent.ExecutionException.class).hasCauseInstanceOf(com.yuewei.plm.common.exception.BusinessException.class).hasStackTraceContaining("不能删除");
            assertThat(jdbc.queryForObject("select deleted_flag from plm_product where product_id=?",Integer.class,id)).isZero();
            jdbc.update("delete from plm_product where product_id=?",child);
        } finally {release.countDown();pool.shutdownNow();pool.awaitTermination(10,java.util.concurrent.TimeUnit.SECONDS);jdbc.update("delete from plm_product where parent_product_id=? and product_code=?",id,code+"-CHILD");jdbc.update("delete from plm_product where product_id=? and product_code=?",id,code);}
    }

}
